#!/usr/bin/env python3
# skye_step10.py -- the loch: tap-to-move, taught on stepping stones.
# Run from the repo root, after skye_step9.py:
#   python3 skye_step10.py
#   node tools/map-editor/generators/skye_gen.mjs
#
# SHORE (skye_cladach): the ravine/ridge/knoll are gone; the headland top is
# open ground running north. After the climb: "Maith go leor. Chuig an
# loch!" -- she dashes off and vanishes. Tap-to-move stays off until the
# loch has taught it. The crane is gone for good.
#
# LOCH (new map, skye_loch, between the shore and the machaire): two pools
# of stepping stones. She waits across each; stepping by d-pad earns "Ná
# féach ar do chosa", then "Féach ormsa" and a pulsing ring at her feet.
# Step off a stone and you're dunked (splash, fade, back to the start of
# the pool, a dry remark, a stronger hint). Water is walkable for the d-pad
# but blocked for the pathfinder, so a tapped route only lands on stones.
# Every diagonal hop has a corner stone, so the d-pad can always make it.
# Ends with lesson_movement, a line about more to learn, and her exit.
#
# Machaire's south exit now leads to the loch.
# Idempotent.

import pathlib, sys

FILES = {
 "tools/map-editor/generators/skye_gen.mjs": "// skye_gen.mjs\n// Generates the five Isle of Skye training-ground maps into\n// public/maps/skyeMaps/. PLACEHOLDER TERRAIN: enough shape to read each\n// place and walk the whole island; every map will get its own proper\n// pass later.\n//\n//          skye_dun          dome of rock, sea behind it to the north\n//             |\n//        skye_droichead      gorge band of sea, 3-wide bridge across\n//             |\n//        skye_machaire ---- skye_faiche\n//             |\n//         skye_cladach       strand + sea along the south\n//\n// Exits are 5-tile corridors centred on each edge; entries mirror the\n// bog maps' convention (arrive 3 tiles in, position carried from source).\n// pathDist gives the trails PGR's mud tint.\n//\n// Deterministic (seeded) -- reruns produce identical maps.\n//\n// Usage:  node tools/map-editor/generators/skye_gen.mjs\n\nimport { writeFileSync, mkdirSync } from 'fs'\nimport { createNoise2D } from 'simplex-noise'\nimport { fileURLToPath } from 'url'\nimport { dirname, resolve } from 'path'\n\nconst __dirname  = dirname(fileURLToPath(import.meta.url))\nconst OUTPUT_DIR = resolve(__dirname, '../../../public/maps/skyeMaps')\n\nconst W = 36, H = 36\nconst MID = 18, HALF = 2              // corridor = cols/rows 16..20\nconst GRASS = [839, 840], STRAND = 731, SEA = 1625\n\nconst LEGEND = { '0': 'overlay', '731': 'waterside', '839': 'grass', '840': 'grass', '1625': 'water',\n                 '44': 'bramble', '45': 'bramble', '46': 'bramble', '47': 'bramble', '48': 'bramble',\n                 '154': 'stone', '155': 'stone', '156': 'stone' }\n\nfunction mulberry32(seed) {\n  return () => {\n    seed |= 0; seed = seed + 0x6D2B79F5 | 0\n    let t = Math.imul(seed ^ seed >>> 15, 1 | seed)\n    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t\n    return ((t ^ t >>> 14) >>> 0) / 4294967296\n  }\n}\n\nconst grid = (w, h, f) => Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => f(x, y)))\nconst corridor = () => Array.from({ length: HALF * 2 + 1 }, (_, i) => MID - HALF + i)\n\n// ── exits / entries ─────────────────────────────────────────────────────────\nconst OPPOSITE = { north: 'south', south: 'north', east: 'west', west: 'east' }\n\nfunction exitTiles(dir) {\n  const c = corridor()\n  if (dir === 'north') return c.map(x => [x, 0])\n  if (dir === 'south') return c.map(x => [x, H - 1])\n  if (dir === 'west')  return c.map(y => [0, y])\n  return c.map(y => [W - 1, y])\n}\n\nconst ENTRIES = {\n  north: { y: 3,     xFromSource: true },\n  south: { y: H - 4, xFromSource: true },\n  west:  { x: 3,     yFromSource: true },\n  east:  { x: W - 4, yFromSource: true },\n}\n\n// ── trails -> pathDist ──────────────────────────────────────────────────────\nconst EDGE_PT = { north: [MID, 0], south: [MID, H - 1], west: [0, MID], east: [W - 1, MID] }\n\nfunction segDist(px, py, [ax, ay], [bx, by]) {\n  const dx = bx - ax, dy = by - ay\n  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy || 1)))\n  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy))\n}\n\nfunction pathDistFor(points, falloff = 3) {\n  return grid(W, H, (x, y) => {\n    let d = Infinity\n    for (const [a, b] of points) d = Math.min(d, segDist(x, y, a, b))\n    return +Math.min(1, d / falloff).toFixed(3)\n  })\n}\n\n// ── per-map terrain ─────────────────────────────────────────────────────────\n// Each returns { tile(x,y) -> gid, height(vx,vy) -> number, trail: [[a,b],...], spawn? }\n\nconst MAPS = {\n  skye_cladach: {\n    exits: { north: 'skye_loch' },\n    // At the foot of the headland; jetty and boat behind (south).\n    spawn: { x: MID, y: 28 },\n    // Arriving back from the loch: on the headland top.\n    entries: { north: { x: MID, y: 2 } },\n    build(n, rng) {\n      // ── Layout (keep in sync with skye/skyeCladach.js) ────────────────\n      //   rows 30+   sea; row 29 strand; jetty (18-19, 30-33), boat (34)\n      //   rows 27-28 the foot of the headland, rocky\n      //   THE WALL   three stone risers (rows 26, 24, 22) with one-row\n      //              terraces between (25, 23). Every riser tile is solid\n      //              (blockMask) except ONE per riser -- the hidden stair,\n      //              drawn identically to the rest: only her calls find it.\n      //                gaps: (17,26)  (19,24)  (16,22)\n      //   rows 0-21 the headland top, open ground running north to the\n      //              loch. Uathach waits at (17,20).\n      const LV = [0.1, 1.1, 2.1, 3.1]              // foot, terrace 1, terrace 2, top\n      const FLOOR = 1.2                            // ravine floor\n      const GAPS = { 26: 17, 24: 19, 22: 16 }      // riser row -> stair column\n      const JETTY = { x0: 18, x1: 19, y0: 30, y1: 33, deckH: 0.28 }\n      const inBox = (b, x, y) => x >= b.x0 && x <= b.x1 && y >= b.y0 && y <= b.y1\n\n      // Tile height by class. Risers belong to the level BELOW them; the\n      // vertex rule below lifts their north edge, making each riser a\n      // half-step slope (0.5): stone to look at, climbable where open.\n      const tileH = (x, y) => {\n        x = Math.max(0, Math.min(W - 1, x)); y = Math.max(0, Math.min(H - 1, y))\n        if (y >= 29) return 0\n        if (y >= 26) return LV[0]\n        if (y >= 24) return LV[1]\n        if (y >= 22) return LV[2]\n        return LV[3]                                 // the top, all the way north\n      }\n      const isSea = (x, y) => !inBox(JETTY, x, y) && y >= 30\n\n      return {\n        tile: (x, y) => {\n          if (inBox(JETTY, x, y)) return GRASS[0]        // walkable; the deck is drawn over it\n          if (y >= 30) return SEA\n          if (y === 29) return STRAND\n          return null\n        },\n        overlay: () => 0,\n        // vertex = the highest tile touching it (+ a whisper of noise)\n        height: (x, y) => {\n          if (inBox({ ...JETTY, x1: JETTY.x1 + 1, y1: JETTY.y1 + 1 }, x, y)) return JETTY.deckH\n          if (y >= 30) return 0\n          const h = Math.max(tileH(x - 1, y - 1), tileH(x, y - 1), tileH(x - 1, y), tileH(x, y))\n          return h + (y >= 29 ? 0 : (n(x * 0.3, y * 0.3) + 1) * 0.02)\n        },\n        trail: [[[16, 21], [MID, 0]]],\n        trailFalloff: 1.5,\n        extra: {\n          // solid: every riser tile but the stair\n          blockMask: grid(W, H, (x, y) => (y in GAPS && x !== GAPS[y]) ? 1 : 0),\n          // the wall, its terraces and its foot read as bare rock (the\n          // risers also get SteepFaceRenderer's stone texture on top)\n          stoneTint: grid(W, H, (x, y) =>\n            (y >= 22 && y <= 28 && !inBox(JETTY, x, y)) ? 1 : 0),\n          // Dressed as harbour stonework by skye/harbourWall.js\n          wall: { risers: [26, 24, 22], ledges: [25, 23], quay: [27, 28], gaps: GAPS },\n          jetty: JETTY,\n          boat: { x: 18.9, y: 34.4, width: 2.3 },\n        },\n      }\n    },\n  },\n\n  skye_loch: {\n    exits: { north: 'skye_machaire', south: 'skye_cladach' },\n    spawn: { x: MID, y: 27 },\n    entries: { south: { x: MID, y: 27 }, north: { x: MID, y: 2 } },\n    build(n) {\n      // ── Layout (keep in sync with skye/skyeLoch.js) ───────────────────\n      //   rows 25+   south bank (arrival from the shore)\n      //   POOL A     rows 17-24, stepping stones from (18,24) to (19,17)\n      //   rows 11-16 middle bank; Uathach waits first at (18,15)\n      //   POOL B     rows 5-10, stepping stones from (18,10) to (19,5)\n      //   rows 0-4   north bank; her second spot (18,3); exit to machaire\n      // Pool water is LOCH (1679): walkable for the d-pad (step off a stone\n      // and you go in -- skyeLoch.js dunks you) but blocked for the\n      // pathfinder, so a tapped route only ever lands on stones.\n      const LOCH = 1679\n      const inPool = (y) => (y >= 17 && y <= 24) || (y >= 5 && y <= 10)\n      // Every diagonal hop also has a corner stone, so the d-pad can always\n      // cross in straight steps (longer, and easy to misstep); a tap takes\n      // the diagonal shortcuts.\n      const STONES = [\n        // pool A\n        [18,24],[18,23],[17,23],[16,23],[16,22],[16,21],[16,20],[17,20],[17,19],\n        [18,19],[18,18],[19,18],[19,17],\n        // pool B\n        [18,10],[18,9],[18,8],[19,8],[20,8],[20,7],[20,6],[19,6],[19,5],\n      ]\n      const stoneSet = new Set(STONES.map(([x, y]) => `${x},${y}`))\n      const isStone = (x, y) => stoneSet.has(`${x},${y}`)\n      return {\n        tile: (x, y) => inPool(y) ? LOCH : null,\n        overlay: () => 0,\n        height: (x, y) => {\n          // vertex: water if any touching tile is open water; stones stand\n          // a little proud of it\n          const touch = [[x - 1, y - 1], [x, y - 1], [x - 1, y], [x, y]]\n          const wet = touch.some(([tx, ty]) => inPool(ty) && !isStone(tx, ty))\n          const stone = touch.some(([tx, ty]) => isStone(tx, ty))\n          if (wet && !stone) return 0\n          if (stone) return 0.12\n          return 0.22 + (n(x * 0.2, y * 0.2) + 1) * 0.06\n        },\n        trail: [[[MID, 35], [MID, 25]], [[19, 16], [MID, 11]], [[19, 4], [MID, 0]]],\n        trailFalloff: 1.3,\n        extra: {\n          stones: STONES,\n          uathachSpots: [[18, 15], [18, 3]],\n          poolStarts: { A: [18, 25], B: [18, 11] },\n        },\n      }\n    },\n  },\n\n  skye_machaire: {\n    exits: { north: 'skye_droichead', south: 'skye_loch', east: 'skye_faiche' },\n    build(n) {\n      return {\n        tile: () => null,\n        height: (x, y) => (n(x * 0.12, y * 0.12) + 1) * 0.12,\n        trail: [[EDGE_PT.south, [MID, MID]], [[MID, MID], EDGE_PT.north], [[MID, MID], EDGE_PT.east]],\n      }\n    },\n  },\n\n  skye_faiche: {\n    exits: { west: 'skye_machaire' },\n    build(n) {\n      return {\n        tile: () => null,\n        height: (x, y) => (n(x * 0.1, y * 0.1) + 1) * 0.03,\n        trail: [[EDGE_PT.west, [MID, MID]]],\n      }\n    },\n  },\n\n  skye_droichead: {\n    exits: { north: 'skye_dun', south: 'skye_machaire' },\n    build(n) {\n      const GORGE_TOP = 15, GORGE_BOT = 19          // tile rows of the gorge\n      const onBridge = x => x >= MID - 1 && x <= MID + 1\n      return {\n        tile: (x, y) => (y >= GORGE_TOP && y <= GORGE_BOT && !onBridge(x)) ? SEA : null,\n        height: (x, y) => {\n          // vertex rows strictly inside the gorge drop to sea level, except\n          // under the bridge deck (vertex cols MID-1..MID+2)\n          const inGorge  = y > GORGE_TOP && y <= GORGE_BOT\n          const underDeck = x >= MID - 1 && x <= MID + 2\n          if (inGorge && !underDeck) return 0\n          return 0.8 + (n(x * 0.15, y * 0.15) + 1) * 0.05\n        },\n        trail: [[EDGE_PT.south, EDGE_PT.north]],\n      }\n    },\n  },\n\n  skye_dun: {\n    exits: { south: 'skye_droichead' },\n    build(n) {\n      const cx = MID, cy = 16, SIGMA = 6, PEAK = 1.6\n      return {\n        tile: (x, y) => y <= 4 ? SEA : null,\n        height: (x, y) => {\n          if (y <= 4) return 0\n          const g = PEAK * Math.exp(-((x - cx) ** 2 + (y - cy) ** 2) / (2 * SIGMA * SIGMA))\n          return 0.8 + g + (n(x * 0.2, y * 0.2) + 1) * 0.04\n        },\n        trail: [[EDGE_PT.south, [cx, cy]]],\n      }\n    },\n  },\n}\n\n// ── build ───────────────────────────────────────────────────────────────────\nmkdirSync(OUTPUT_DIR, { recursive: true })\n\nObject.entries(MAPS).forEach(([name, def], i) => {\n  const rng   = mulberry32(0x5C1A + i * 101)\n  const noise = createNoise2D(rng)\n  const t     = def.build(noise, rng)\n\n  const layer0 = grid(W, H, (x, y) => t.tile(x, y) ?? GRASS[rng() < 0.5 ? 0 : 1])\n  const layer1 = grid(W, H, (x, y) => t.overlay?.(x, y) ?? 0)\n  const heightMap = grid(W + 1, H + 1, (x, y) => +t.height(x, y).toFixed(4))\n\n  const exits = {}, entries = {}\n  const openCols = new Set(), openRows = new Set()\n  for (const [dir, dest] of Object.entries(def.exits)) {\n    exits[dir] = { tiles: exitTiles(dir), destination: dest, entryPoint: OPPOSITE[dir] }\n    entries[dir] = def.entries?.[dir] ?? ENTRIES[dir]\n    ;(dir === 'north' || dir === 'south' ? openCols : openRows)\n      .add(MID - 2).add(MID - 1).add(MID).add(MID + 1).add(MID + 2)\n  }\n\n  const map = {\n    name, width: W, height: H,\n    layers: [layer0, layer1],\n    heightMap, legend: LEGEND,\n    spawns: { player: def.spawn ?? { x: MID, y: MID } },\n    exits, entries,\n    pathDist: pathDistFor(t.trail, t.trailFalloff),\n    ...(t.extra || {}),\n    border: { openCols: [...openCols].sort((a, b) => a - b), openRows: [...openRows].sort((a, b) => a - b) },\n  }\n\n  writeFileSync(resolve(OUTPUT_DIR, `${name}.json`), JSON.stringify(map))\n  console.log(`[skye_gen] ${name}.json  exits: ${Object.keys(exits).join(', ')}`)\n})\n",
 "js/game/scenes/locations/skye/skyeCladach.js": "// skyeCladach.js\n// Location: js/game/scenes/locations/skye/skyeCladach.js\n//\n// The shore: the first half of Uathach's movement lesson. (The second\n// half -- tap-to-move -- is at the loch: skyeLoch.js.)\n//\n//   0. ARRIVAL -- the player stands on the quay at the foot of a stepped\n//      harbour wall, jetty and boat behind them, Uathach on the top. After\n//      a few seconds, or on the first tap / d-pad press, her conversation\n//      opens by itself: starting a conversation isn't something to\n//      discover yet.\n//   1. THE CLIMB -- she calls steps in Irish (forward, left, right only);\n//      the called d-pad button glows, fading over the sequence\n//      (stepDrill.js); a wrong or extra step is corrected and undone. Each\n//      riser of the wall is solid but for one carved stair; her calls walk\n//      the player up them, ending beside her on the top. Starts when the\n//      dialogue sets `drill_start`.\n//   2. OFF TO THE LOCH -- \"Maith go leor. Chuig an loch!\" and she dashes\n//      off north and vanishes. The player follows, over the map edge.\n//\n// Tap-to-move is OFF on this map until `lesson_movement` (set at the loch):\n// the loch is where it's introduced.\n//\n// THE BOAT at the jetty head asks whether to leave the island (the exit\n// from the tutorial to the main adventure). Its dialogue sets\n// `leave_skye`, a one-off trigger the scene clears as it acts on it.\n//\n// Her lines are captions (skyeCaption.js), not cards: cards hide the\n// d-pad, and here the player moves while she talks.\n//\n// NOTES: drill_start (dialogue) -> drill_done -> [loch] lesson_movement\n//\n// Layout constants must match skye_gen.mjs (skye_cladach).\n\nimport SkyeScene, { SKYE_GID } from './skyeScene.js'\nimport { GameState } from '../../../systems/gameState.js'\nimport SkyeCaption from './skyeCaption.js'\nimport StepDrill from './stepDrill.js'\nimport { dash, dustPuff, figureBox, moveFigure } from './dustDash.js'\nimport ShoreProps from './shoreProps.js'\nimport HarbourWall, { combineStructures } from './harbourWall.js'\nimport SteepFaceRenderer from '../../../effects/steepFaceRenderer.js'\nimport { initReturnCrossing } from '../../returnCrossing.js'\nimport { GameSettings } from '../../../settings/gameSettings.js'\n\nconst TOP = { x0: 1, x1: 34, y0: 0, y1: 21 }        // the headland top\nconst EXIT_DASH = [18, 3]                           // where she dashes before vanishing\nconst INTRO_DELAY_MS = 5000\nconst NUDGE_MS = 6000\n\n// From the landing (18,28): through the stairs at (17,26), (19,24) and\n// (16,22) to (16,21) on the top, beside her. A wrong or extra step is\n// undone, so the route is always exact.\nconst DRILL = [\n  { dir: 'forward', ga: 'Céim ar aghaidh.', en: 'A step forward.',      glow: 1 },\n  { dir: 'left',    ga: 'Céim ar chlé.',    en: 'A step to the left.',  glow: 1 },\n  { dir: 'forward', ga: 'Céim ar aghaidh.', en: 'A step forward.',      glow: 1 },\n  { dir: 'forward', ga: 'Ar aghaidh arís.', en: 'Forward again.',       glow: 1 },\n  { dir: 'right',   ga: 'Céim ar dheis.',   en: 'A step to the right.', glow: 1 },\n  { dir: 'right',   ga: 'Ar dheis arís.',   en: 'Right again.',         glow: 0.5 },\n  { dir: 'forward', ga: 'Ar aghaidh.',      en: 'Forward.',             glow: 0.5 },\n  { dir: 'forward', ga: 'Arís.',            en: 'Again.',               glow: 0.25 },\n  { dir: 'left',    ga: 'Ar chlé.',         en: 'Left.',                glow: 0.25 },\n  { dir: 'left',    ga: 'Ar chlé.',         en: 'Left.',                glow: 0 },\n  { dir: 'left',    ga: 'Arís.',            en: 'Again.',               glow: 0 },\n  { dir: 'forward', ga: 'Ar aghaidh.',      en: 'Forward.',             glow: 0 },\n  { dir: 'forward', ga: 'Suas leat!',       en: 'Up you come!',         glow: 0 },\n]\n\nconst LINES = {\n  intro:  { ga: 'Éist liom, agus déan mar a deirim.',\n            en: 'Listen to me, and do as I say.' },\n  comeUp: { ga: 'Tar aníos anseo.', en: 'Come up here.' },\n  nudge:  { ga: 'Aníos!', en: 'Up!' },\n  done:   { ga: 'Maith go leor. Chuig an loch!',\n            en: 'Good enough. To the loch!' },\n}\n\nconst inBox = (b, x, y) => x >= b.x0 && x <= b.x1 && y >= b.y0 && y <= b.y1\n\nexport class SkyeCladach extends SkyeScene {\n  constructor() { super({ key: 'skye_cladach' }) }\n  getMapKey() { return 'skye_cladach' }\n\n  preload() {\n    super.preload()\n    this.load.image('boat', '/assets/boat.png')\n  }\n\n  async create(data) {\n    await super.create(data)\n    if (!this.player) return                    // base create failed (logged)\n\n    this._caption = new SkyeCaption()\n    this._uathach = this._findFigure(SKYE_GID.UATHACH)\n    this._boat    = this._findFigure(SKYE_GID.BOAT)\n    if (this._boat) this._boat.flag.hidden = true   // ShoreProps draws the boat; the flag is just for talking\n    this._phase   = 'free'\n\n    // The wall is dressed as harbour stonework (harbourWall.js); the\n    // generic stone overlay handles any other steep face.\n    const wall = new HarbourWall(this, this.mapData.wall)\n    this.steepFaces = new SteepFaceRenderer(this, { skip: (tx, ty) => wall.ownsRow(ty) })\n    this.perspectiveGround?.setStructures(combineStructures(\n      new ShoreProps(this, { jetty: this.mapData.jetty, boat: this.mapData.boat }),\n      wall,\n    ))\n\n    if (GameState.hasNote('drill_done')) {\n      this._vanishUathach(false)                  // she's gone on to the loch\n    } else if (!GameState.hasNote('drill_start')) {\n      this._phase = 'arrival'\n      this._introTimer = this.time.delayedCall(INTRO_DELAY_MS, () => this._openIntro())\n    }\n\n    this.events.once('shutdown', () => this._teardownLesson())\n  }\n\n  update(time, delta) {\n    this.steepFaces?.update()\n    // Arrival: the first d-pad press opens her conversation instead of\n    // walking. Checked before super.update() so the press never moves.\n    if (this._phase === 'arrival' && this.joystick?.force > 10) {\n      this.joystick.reset?.()\n      this._openIntro()\n    }\n    super.update(time, delta)\n    if (!this.player || !this._caption) return\n    const panelOpen = !!this._encounterPanel?._isOpen\n\n    if (this._phase === 'free' && GameState.hasNote('drill_start') &&\n        !GameState.hasNote('drill_done') && !panelOpen) {\n      this._startDrill()\n    }\n    if (this._phase === 'drill' && !panelOpen) this._drill?.update()\n    if (this._phase === 'comeUp') this._checkClimb(time)\n    if (GameState.hasNote('leave_skye') && !panelOpen) this._leaveSkye()\n  }\n\n  // Taps: during arrival a tap opens her conversation; otherwise tap-to-\n  // move doesn't exist here until the loch has taught it.\n  _onTapBeforePath(canvasX, canvasY) {\n    if (this._phase === 'arrival') { this._openIntro(); return false }\n    return GameState.hasNote('lesson_movement')\n  }\n\n  // ── 0. arrival ───────────────────────────────────────────────────────────\n  _openIntro() {\n    if (this._phase !== 'arrival') return\n    this._phase = 'free'\n    this._introTimer?.remove?.()\n    const panel = this._encounterPanel\n    if (!panel || !this._uathach) return\n    panel.notify({ id: 'fixed:uathach', visual: this._uathach.flag.visual }, this._uathach.zone)\n    panel._openPanel()\n  }\n\n  // ── 1. the climb ─────────────────────────────────────────────────────────\n  _startDrill() {\n    this._phase = 'drill'\n    const champ = this.registry.get('selectedChampion') || window.selectedChampion\n    const female = champ?.pronouns?.ga?.subject === 'sí'\n    this._drill = new StepDrill(this, {\n      caption: this._caption, steps: DRILL, female,\n      onDone: () => this._drillDone(),\n    })\n    this._drill.start({ ...LINES.intro, holdMs: 2600 })\n  }\n\n  _drillDone() {\n    this._drill?.destroy()\n    this._drill = null\n    GameState.addNote('drill_done')\n    if (this._onTop()) return this._offToLoch()\n    this._phase = 'comeUp'\n    this._nextNudge = null\n    this._caption.show(LINES.comeUp.ga, LINES.comeUp.en)\n  }\n\n  // Fallback only: the undo keeps the calls exact, so the climb normally\n  // ends on the top. If it doesn't, wait for them to get up there, nudging\n  // now and then, alternating the short and the full call.\n  _checkClimb(time) {\n    if (this._onTop()) return this._offToLoch()\n    if (this._nextNudge == null) this._nextNudge = time + NUDGE_MS\n    if (time < this._nextNudge) return\n    this._nextNudge = time + NUDGE_MS\n    this._nudgeFlip = !this._nudgeFlip\n    const line = this._nudgeFlip ? LINES.nudge : LINES.comeUp\n    this._caption.show(line.ga, line.en, 2500)\n  }\n\n  // ── 2. off to the loch ───────────────────────────────────────────────────\n  _offToLoch() {\n    this._phase = 'dash'\n    this._caption.show(LINES.done.ga, LINES.done.en, 3000)\n    this.time.delayedCall(1400, () => {\n      if (!this._uathach) { this._phase = 'free'; return }\n      dash(this, {\n        flag: this._uathach.flag, zone: this._uathach.zone, to: EXIT_DASH,\n        onArrive: () => this.time.delayedCall(500, () => {\n          this._vanishUathach(true)\n          this._phase = 'free'\n        }),\n      })\n    })\n  }\n\n  // Gone: flag hidden, zone moved off the map so her badge can't appear.\n  _vanishUathach(puff) {\n    const u = this._uathach\n    if (!u) return\n    if (puff) {\n      const box = figureBox(this, u.flag.tileX, u.flag.tileY)\n      if (box) dustPuff(this, box, 0.4)\n    }\n    u.flag.hidden = true\n    moveFigure(this, u.flag, u.zone, [-20, -20])\n  }\n\n  // ── the boat: leaving the island ─────────────────────────────────────────\n  _leaveSkye() {\n    GameState.removeNote('leave_skye')\n    if (this._leaving) return\n    this._leaving = true\n    const champ = this.registry.get('selectedChampion') || window.selectedChampion\n    this.cameras.main.fadeOut(700, 0, 0, 0)\n    this.time.delayedCall(750, () => {\n      const container = document.getElementById('gameContainer')\n      if (container) container.style.background = '#000'\n      initReturnCrossing(champ, GameSettings.englishOpacity, () => {\n        if (window.startGame) window.startGame(champ, { startScene: 'd3_sea' })\n        else this.scene.start('d3_sea')\n      })\n    })\n  }\n\n  // ── helpers ──────────────────────────────────────────────────────────────\n  _onTop() {\n    const ts = this.tileSize\n    return inBox(TOP, Math.floor(this.player.logicalX / ts), Math.floor(this.player.logicalY / ts))\n  }\n\n  _findFigure(gid) {\n    const flag = this.perspectiveGround?._encounterFlags?.find(f => f.visual?.gid === gid)\n    if (!flag) return null\n    const ts = this.tileSize\n    const zone = this.interactables?.find(z =>\n      z.getData('type') === 'fixed_encounter' &&\n      Math.floor((z.getData('logicalX') ?? z.x) / ts) === flag.tileX &&\n      Math.floor((z.getData('logicalY') ?? z.y) / ts) === flag.tileY)\n    if (!zone) return null\n    return { flag, zone }\n  }\n\n  _teardownLesson() {\n    this.steepFaces?.destroy?.()\n    this.steepFaces = null\n    this._introTimer?.remove?.()\n    this._drill?.destroy()\n    this._drill = null\n    this._phase = 'free'\n    this._caption?.destroy()\n    this._caption = null\n  }\n}\n",
 "js/game/scenes/locations/skye/skyeLoch.js": "// skyeLoch.js\n// Location: js/game/scenes/locations/skye/skyeLoch.js\n//\n// The loch: the second half of Uathach's movement lesson -- tap-to-move.\n// Two pools of stepping stones in a row, a strip of bank between.\n//\n//   ROUND A  She waits across the first pool: \"Tar chugam.\" Stepping by\n//            d-pad, she mutters \"Ná féach ar do chosa.\" now and then; after\n//            a while, \"Féach ormsa.\" and a pulsing ring appears at her feet\n//            -- the same marker a tap leaves -- suggesting \"touch here\".\n//            Reach her by tap: \"Sin é.\" Step all the way: \"Bhí tú ag\n//            féachaint ar do chosa an t-am ar fad.\"\n//   ROUND B  She dashes across the second pool: one more go (ring already\n//            showing if round A was walked). Then a line about there being\n//            more to learn, and she's off to the machaire.\n//\n// THE DUNK  Loch water is walkable for the d-pad but blocked for the\n//           pathfinder (_buildWalkGrid), so stepping off a stone puts you\n//           in, while a tapped route only ever lands on stones. A dunk:\n//           splash, fade, back to the start of that pool, a dry remark --\n//           and the hint gets stronger each time. After the lesson a dunk\n//           just puts you back on your last dry footing.\n//\n// Tap-to-move is ON here: this is where it's introduced.\n// NOTES: sets lesson_movement at the end of round B.\n//\n// Layout (stones, her spots, pool starts) comes from the map JSON --\n// see skye_gen.mjs (skye_loch).\n\nimport SkyeScene, { SKYE_GID } from './skyeScene.js'\nimport { GameState } from '../../../systems/gameState.js'\nimport SkyeCaption from './skyeCaption.js'\nimport LochStones from './lochStones.js'\nimport { dash, dustPuff, figureBox, moveFigure, splash } from './dustDash.js'\n\nconst LOCH = 1679\nconst NUDGE_EVERY = 4        // d-pad steps between nudges\nconst RING_AFTER  = 6        // d-pad steps before \"look at me\" + the ring\n\nconst LINES = {\n  come:      { ga: 'Tar chugam.', en: 'Come to me.' },\n  feet:      { ga: 'Ná féach ar do chosa.', en: 'Don\\'t look at your feet.' },\n  lookAtMe:  { ga: 'Féach ormsa.', en: 'Look at me.' },\n  explicit:  { ga: 'Féach ormsa. Leag do mhéar orm.', en: 'Look at me. Put your finger on me.' },\n  wet:       { ga: 'Fliuch?', en: 'Wet?' },\n  wetAgain:  { ga: 'Bhí tú ag féachaint ar do chosa arís.', en: 'You were looking at your feet again.' },\n  tappedA:   { ga: 'Sin é. Féach ar an áit a bhfuil tú ag dul.', en: 'That\\'s it. Look where you\\'re going.' },\n  walkedA:   { ga: 'Bhí tú ag féachaint ar do chosa an t-am ar fad.', en: 'You were looking at your feet the whole time.' },\n  againB:    { ga: 'Arís.', en: 'Again.' },\n  againBHint:{ ga: 'Arís. Féach ormsa an uair seo.', en: 'Again. Look at me this time.' },\n  tappedB:   { ga: 'Sin é. Tá sé agat.', en: 'That\\'s it. You have it.' },\n  walkedB:   { ga: 'Bhuel. Tiocfaidh sé leat.', en: 'Well. It\\'ll come to you.' },\n  more:      { ga: 'Tá tuilleadh le foghlaim fós. Neart.', en: 'There\\'s more to learn yet. Plenty.' },\n}\n\nexport class SkyeLoch extends SkyeScene {\n  constructor() { super({ key: 'skye_loch' }) }\n  getMapKey() { return 'skye_loch' }\n\n  // Loch water: walkable (you can step in -- and get dunked)...\n  getExtraUnwalkableGIDs() {\n    const s = super.getExtraUnwalkableGIDs()\n    s.delete(LOCH)\n    return s\n  }\n\n  // ...but never part of a tapped route: the pathfinder sees only stones.\n  _buildWalkGrid() {\n    const g = super._buildWalkGrid()\n    const L0 = this.mapData.layers[0]\n    for (let y = 0; y < g.length; y++) {\n      for (let x = 0; x < g[y].length; x++) {\n        if (L0[y]?.[x] === LOCH && !this._isStone(x, y)) g[y][x] = false\n      }\n    }\n    return g\n  }\n\n  _isStone(x, y) {\n    if (!this._stoneSet) this._stoneSet = new Set((this.mapData?.stones || []).map(([a, b]) => `${a},${b}`))\n    return this._stoneSet.has(`${x},${y}`)\n  }\n\n  async create(data) {\n    await super.create(data)\n    if (!this.player) return\n\n    this._caption = new SkyeCaption()\n    this._uathach = this._findFigure(SKYE_GID.UATHACH)\n    this.perspectiveGround?.setStructures(new LochStones(this, this.mapData.stones))\n    this._spots  = this.mapData.uathachSpots      // [A, B]\n    this._starts = this.mapData.poolStarts        // { A, B }\n    this._dunks  = 0\n\n    // A stone sits on a water tile; stood on, it's ground, not water (no\n    // wading slow-down or sink).\n    const tm = this.terrainManager\n    if (tm?.getTerrainByTileType) {\n      const orig = tm.getTerrainByTileType.bind(tm)\n      tm.getTerrainByTileType = (t) => this._onStone() ? tm.terrainTypes.normal : orig(t)\n    }\n\n    // Tapped arrivals: setPath is how tap-to-move walks.\n    const origSetPath = this.player.setPath.bind(this.player)\n    this.player.setPath = (steps) => {\n      if (steps?.length) { this._tapped = true; this._pathSteps = steps.length }\n      return origSetPath(steps)\n    }\n\n    this._ring = this.add.graphics().setScrollFactor(0).setDepth(15)\n\n    if (GameState.hasNote('lesson_movement')) {\n      this._vanishUathach(false)\n      this._phase = 'free'\n    } else {\n      this._beginRound('A', 1200)\n    }\n\n    this.events.once('shutdown', () => this._teardownLesson())\n  }\n\n  update(time, delta) {\n    if (this._dunking) this.joystick?.reset?.()          // no moving while under\n    super.update(time, delta)\n    if (!this.player || !this._caption) return\n\n    const ts = this.tileSize\n    const tx = Math.floor(this.player.logicalX / ts), ty = Math.floor(this.player.logicalY / ts)\n    const moved = !this._lastTile || this._lastTile[0] !== tx || this._lastTile[1] !== ty\n    this._lastTile = [tx, ty]\n\n    const inWater = this.mapData.layers[0][ty]?.[tx] === LOCH && !this._isStone(tx, ty)\n    if (!inWater && !this._dunking) this._lastSafe = [tx, ty]\n    if (inWater && !this._dunking) this._dunk()           // always: lesson or not\n\n    if (this._phase === 'crossing') {\n      if (moved && !inWater && !this._dunking) this._countStep()\n      const spot = this._spots[this._round === 'A' ? 0 : 1]\n      if (!this._dunking && this._near(spot, 1.6)) this._roundDone()\n    }\n    this._drawRing(time)\n  }\n\n  // Taps work here (this is the lesson), just not mid-dunk.\n  _onTapBeforePath() { return !this._dunking }\n\n  // ── rounds ───────────────────────────────────────────────────────────────\n  _beginRound(round, delayMs, line = LINES.come) {\n    this._round = round\n    this._tapped = false\n    this._pathSteps = 0\n    this._padSteps = 0\n    this._phase = 'crossing'\n    this.time.delayedCall(delayMs, () => this._say(line, 3000))\n  }\n\n  // A d-pad step (not one of a tapped route's): nudge now and then; after\n  // a while, the stronger hint and the ring.\n  _countStep() {\n    if (this._pathSteps > 0) { this._pathSteps--; return }\n    this._padSteps++\n    if (!this._ringOn && this._padSteps >= RING_AFTER) {\n      this._ringOn = true\n      this._say(this._dunks >= 2 ? LINES.explicit : LINES.lookAtMe, 3200)\n    } else if (this._padSteps % NUDGE_EVERY === 0) {\n      // once the ring is up, point the words at it too\n      this._nudgeFlip = !this._nudgeFlip\n      this._say(this._ringOn && this._nudgeFlip ? LINES.lookAtMe : LINES.feet, 2400)\n    }\n  }\n\n  _roundDone() {\n    this._phase = 'talk'\n    const tapped = this._tapped\n    if (this._round === 'A') {\n      this._say(tapped ? LINES.tappedA : LINES.walkedA, 3400)\n      this.time.delayedCall(3200, () => this._dashTo(this._spots[1], () => {\n        if (!tapped) this._ringOn = true\n        this._beginRound('B', 400, tapped ? LINES.againB : LINES.againBHint)\n      }))\n    } else {\n      GameState.addNote('lesson_movement')\n      this._ringOn = false\n      this._say(tapped ? LINES.tappedB : LINES.walkedB, 3000)\n      this.time.delayedCall(3000, () => this._say(LINES.more, 3200))\n      this.time.delayedCall(5600, () => this._dashTo([22, 1], () => {\n        this.time.delayedCall(400, () => { this._vanishUathach(true); this._phase = 'free' })\n      }))\n    }\n  }\n\n  _dashTo(to, onArrive) {\n    if (!this._uathach) { onArrive?.(); return }\n    dash(this, { flag: this._uathach.flag, zone: this._uathach.zone, to, onArrive })\n  }\n\n  // ── the dunk ─────────────────────────────────────────────────────────────\n  // During the lesson: back to the start of the pool, with a remark and a\n  // stronger hint. Any other time: quietly back to the last dry footing.\n  _dunk() {\n    const lesson = this._phase === 'crossing'\n    this._dunking = true\n    this.player.clearPath?.()\n    this._pathSteps = 0\n    const ts = this.tileSize\n    splash(this, figureBox(this, Math.floor(this.player.logicalX / ts), Math.floor(this.player.logicalY / ts)))\n    if (lesson) this._dunks++\n    const back = lesson ? this._starts[this._round] : (this._lastSafe || this._starts.A)\n    this.time.delayedCall(450, () => this._fade(1, 260))\n    this.time.delayedCall(800, () => {\n      this._teleport(back)\n      this._fade(0, 320)\n      if (lesson) {\n        this._padSteps = 0\n        this._ringOn = true                                // the hint grows\n        this._say(this._dunks === 1 ? LINES.wet : this._dunks === 2 ? LINES.explicit : LINES.wetAgain, 3000)\n      }\n      this.time.delayedCall(350, () => { this._dunking = false })\n    })\n  }\n\n  _teleport([tx, ty]) {\n    const ts = this.tileSize, px = tx * ts + ts / 2, py = ty * ts + ts / 2\n    const p = this.player\n    p.clearPath?.()\n    p.isMoving = false\n    p.logicalX = p.targetX = p.startX = px\n    p.logicalY = p.targetY = p.startY = py\n    this._camProxy?.setPosition(px, py)\n    this.cameras.main.centerOn(px, py)\n    this._lastTile = [tx, ty]\n    this.perspectiveGround?.forceRedraw?.()\n  }\n\n  // A black veil over everything but the d-pad and captions (PGR's canvases\n  // are DOM layers, so a Phaser camera fade wouldn't cover them).\n  _fade(to, ms) {\n    if (!this._veil) {\n      const v = document.createElement('div')\n      v.style.cssText = 'position:fixed;inset:0;background:#000;opacity:0;pointer-events:none;z-index:1000002;transition:opacity 0.25s linear'\n      document.body.appendChild(v)\n      this._veil = v\n    }\n    this._veil.style.transitionDuration = ms + 'ms'\n    this._veil.style.opacity = String(to)\n  }\n\n  // ── the ring: \"touch here\" ───────────────────────────────────────────────\n  _drawRing(time) {\n    const g = this._ring\n    if (!g) return\n    g.clear()\n    const u = this._uathach\n    if (!this._ringOn || !u || u.flag.hidden || this._phase !== 'crossing') return\n    const box = figureBox(this, u.flag.tileX, u.flag.tileY)\n    if (!box) return\n    const t = (Math.sin(time / 260) + 1) / 2\n    g.lineStyle(Math.max(2, box.w * 0.06), 0xf5d060, 0.45 + 0.45 * t)\n    g.strokeEllipse(box.x, box.y, box.w * (1.3 + 0.35 * t), box.w * (0.45 + 0.12 * t))\n  }\n\n  // ── helpers ──────────────────────────────────────────────────────────────\n  _say(line, ms) { this._caption?.show(line.ga, line.en, ms) }\n\n  _onStone() {\n    const p = this.player, ts = this.tileSize\n    if (!p) return false\n    const bx = p.isMoving ? p.startX : p.logicalX, by = p.isMoving ? p.startY : p.logicalY\n    return this._isStone(Math.floor(bx / ts), Math.floor(by / ts))\n  }\n\n  _near([tx, ty], tiles) {\n    const ts = this.tileSize\n    return Math.hypot(this.player.logicalX - (tx + 0.5) * ts,\n                      this.player.logicalY - (ty + 0.5) * ts) <= ts * tiles\n  }\n\n  _vanishUathach(puff) {\n    const u = this._uathach\n    if (!u) return\n    if (puff) {\n      const box = figureBox(this, u.flag.tileX, u.flag.tileY)\n      if (box) dustPuff(this, box, 0.4)\n    }\n    u.flag.hidden = true\n    moveFigure(this, u.flag, u.zone, [-20, -20])\n  }\n\n  _findFigure(gid) {\n    const flag = this.perspectiveGround?._encounterFlags?.find(f => f.visual?.gid === gid)\n    if (!flag) return null\n    const ts = this.tileSize\n    const zone = this.interactables?.find(z =>\n      z.getData('type') === 'fixed_encounter' &&\n      Math.floor((z.getData('logicalX') ?? z.x) / ts) === flag.tileX &&\n      Math.floor((z.getData('logicalY') ?? z.y) / ts) === flag.tileY)\n    if (!zone) return null\n    return { flag, zone }\n  }\n\n  _teardownLesson() {\n    this._ring?.destroy()\n    this._ring = null\n    this._veil?.remove()\n    this._veil = null\n    this._caption?.destroy()\n    this._caption = null\n    this._phase = 'free'\n  }\n}\n",
 "js/game/scenes/locations/skye/lochStones.js": "// lochStones.js\n// Location: js/game/scenes/locations/skye/lochStones.js\n//\n// Stepping stones on the loch: flat, rounded, wet-rimmed, each with a faint\n// ring on the water. Everything here is flat on purpose -- things that\n// stick up (posts, gorse) are hard to read in this camera; stones in water\n// read at a glance.\n//\n// A PGR structure provider (pgr.setStructures), drawn on the ground\n// canvas after each row, so nearer rows paint over farther ones.\n// mapData.stones = [[x, y], ...]\n\nfunction hash(x, y, s = 0) {\n  let h = (x | 0) * 374761393 + (y | 0) * 668265263 + (s | 0) * 2147483647\n  h = (h ^ (h >>> 13)) * 1274126177\n  return ((h ^ (h >>> 16)) >>> 0) / 4294967296\n}\n\nconst TOPS = ['#7d786f', '#8a857b', '#726d65']\n\nexport default class LochStones {\n  constructor(scene, stones) {\n    this.byRow = new Map()\n    for (const [x, y] of stones || []) {\n      if (!this.byRow.has(y)) this.byRow.set(y, [])\n      this.byRow.get(y).push(x)\n    }\n  }\n\n  getEntriesForRow(row) {\n    const cols = this.byRow.get(row)\n    if (!cols) return []\n    return [{ draw: (ctx, pgr) => { for (const c of cols) this._stone(ctx, pgr, c, row) } }]\n  }\n\n  _stone(ctx, pgr, col, row) {\n    const yT = pgr._rowToScreenY(row), yB = pgr._rowToScreenY(row + 1)\n    if (yT == null || yB == null) return\n    const sT = pgr._scaleAtRow(row), sB = pgr._scaleAtRow(row + 1)\n    if (sB < 2) return\n    const lift = (c, r, s) => pgr._vertexH(c, r) * s\n    const tl = { x: pgr._colToScreenX(col, row),         y: yT - lift(col, row, sT) }\n    const tr = { x: pgr._colToScreenX(col + 1, row),     y: yT - lift(col + 1, row, sT) }\n    const bl = { x: pgr._colToScreenX(col, row + 1),     y: yB - lift(col, row + 1, sB) }\n    const br = { x: pgr._colToScreenX(col + 1, row + 1), y: yB - lift(col + 1, row + 1, sB) }\n    const cx = (tl.x + tr.x + bl.x + br.x) / 4\n    const cy = (tl.y + tr.y + bl.y + br.y) / 4 + (bl.y - tl.y) * 0.05\n    const rx = ((tr.x - tl.x) + (br.x - bl.x)) / 2 * 0.43\n    const ry = (bl.y - tl.y) * 0.4\n    const thick = Math.max(1.5, ry * 0.35)\n\n    // ring on the water\n    ctx.strokeStyle = 'rgba(220,235,242,0.22)'\n    ctx.lineWidth = Math.max(1, sB * 0.02)\n    ctx.beginPath(); ctx.ellipse(cx, cy + thick * 0.8, rx * 1.25, ry * 1.25, 0, 0, Math.PI * 2); ctx.stroke()\n\n    // irregular outline, shared by the wet side and the dry top\n    const pts = []\n    for (let i = 0; i < 10; i++) {\n      const a = (i / 10) * Math.PI * 2\n      const k = 0.82 + hash(col, row, i) * 0.22\n      pts.push([Math.cos(a) * rx * k, Math.sin(a) * ry * k])\n    }\n    const path = (dy) => {\n      ctx.beginPath()\n      pts.forEach(([x, y], i) => i ? ctx.lineTo(cx + x, cy + y + dy) : ctx.moveTo(cx + x, cy + y + dy))\n      ctx.closePath()\n    }\n    ctx.fillStyle = '#34322e'; path(thick); ctx.fill()                  // wet side\n    ctx.fillStyle = TOPS[Math.floor(hash(col, row, 20) * TOPS.length)]\n    path(0); ctx.fill()                                                // top\n    ctx.fillStyle = 'rgba(255,255,255,0.12)'                           // dry highlight\n    ctx.beginPath(); ctx.ellipse(cx - rx * 0.2, cy - ry * 0.25, rx * 0.45, ry * 0.3, 0, 0, Math.PI * 2); ctx.fill()\n    if (hash(col, row, 30) < 0.4) {                                    // a crust of lichen\n      ctx.fillStyle = 'rgba(160,168,96,0.5)'\n      ctx.beginPath(); ctx.ellipse(cx + rx * 0.3, cy + ry * 0.1, rx * 0.18, ry * 0.14, 0, 0, Math.PI * 2); ctx.fill()\n    }\n  }\n}\n",
 "js/game/scenes/locations/skye/dustDash.js": "// dustDash.js\n// Location: js/game/scenes/locations/skye/dustDash.js\n//\n// A figure crosses ground in one move, as if it were nothing: a little\n// wind-up, a lunge that streaks and fades in the direction of travel with\n// speed lines, dust left hanging in the air; then the same streak arriving\n// at the far end, a skid, and a second puff. Used by Uathach to cross the\n// hedge maze; available to any Skye teacher.\n//\n//   dash(scene, { flag, zone, to: [tx, ty], onArrive })\n//\n// flag/zone are the PGR flag record and proximity zone of a fixed\n// encounter; they move together. The flag is hidden for the duration and\n// a Phaser image of the same sprite plays the animation in screen space.\n\nconst DUST = [0xc9b89a, 0xb3a07e, 0xd8cdb4]\n\n// Where PGR draws a figure standing on (tx, ty): same maths as its flag\n// billboards -- foot on the tile's south edge, lifted by terrain height.\nexport function figureBox(scene, tx, ty) {\n  const pgr = scene.perspectiveGround\n  if (!pgr) return null\n  const ts = pgr.tileDisplaySize\n  const proj = pgr._projectLogical((tx + 0.5) * ts, (ty + 0.5) * ts, true)\n  if (!proj) return null\n  const lift = ((pgr._vertexH(tx, ty + 1) + pgr._vertexH(tx + 1, ty + 1)) * 0.5)\n             * pgr._scaleAtRow(ty + 1)\n  const w = proj.scale * ts\n  return { x: proj.screenX, y: proj.screenY - lift, w, h: w * 1.2 }\n}\n\n// Dust that hangs, drifts and thins out rather than popping.\nexport function dustPuff(scene, box, drift = 0, count = 10) {\n  if (!box) return\n  const r = Math.max(3, box.w * 0.16)\n  for (let i = 0; i < count; i++) {\n    const c = scene.add.circle(\n      box.x + (Math.random() - 0.5) * box.w * 0.9,\n      box.y - Math.random() * box.h * 0.25,\n      r * (0.7 + Math.random() * 0.7),\n      DUST[i % DUST.length], 0.7\n    ).setScrollFactor(0).setDepth(16)\n    scene.tweens.add({\n      targets: c,\n      scale: 2.2 + Math.random() * 1.2,\n      alpha: 0,\n      x: c.x + drift * box.w * (0.6 + Math.random()) + (Math.random() - 0.5) * r * 3,\n      y: c.y - r * (1 + Math.random() * 2),\n      duration: 1100 + Math.random() * 700,\n      ease: 'Sine.easeOut',\n      onComplete: () => c.destroy(),\n    })\n  }\n}\n\nfunction speedLines(scene, box, ux, uy, ahead = false) {\n  const g = scene.add.graphics().setScrollFactor(0).setDepth(17)\n  g.lineStyle(Math.max(1, box.w * 0.04), 0xf3ead2, 0.9)\n  for (let i = 0; i < 7; i++) {\n    const off = (Math.random() - 0.5) * box.h * 0.9\n    const len = box.w * (1.2 + Math.random() * 1.6)\n    // perpendicular offset across the body, lines trail behind the motion\n    const px = -uy * off, py = ux * off\n    const sx = box.x + px - ux * (ahead ? -box.w * 0.3 : box.w * 0.3)\n    const sy = box.y - box.h * 0.5 + py - uy * (ahead ? -box.w * 0.3 : box.w * 0.3)\n    g.lineBetween(sx, sy, sx - ux * len, sy - uy * len)\n  }\n  scene.tweens.add({ targets: g, alpha: 0, duration: 260, onComplete: () => g.destroy() })\n}\n\nexport function whoosh(scene, volume = 0.22, dur = 0.32, from = 2400, to = 350) {\n  const ctx = scene.sound?.context\n  if (!ctx || ctx.state === 'closed') return\n  const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * dur), ctx.sampleRate)\n  const d = buf.getChannelData(0)\n  for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1\n  const src = ctx.createBufferSource(); src.buffer = buf\n  const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 1.2\n  bp.frequency.setValueAtTime(from, ctx.currentTime)\n  bp.frequency.exponentialRampToValueAtTime(to, ctx.currentTime + dur)\n  const g = ctx.createGain()\n  g.gain.setValueAtTime(0.0001, ctx.currentTime)\n  g.gain.exponentialRampToValueAtTime(volume, ctx.currentTime + 0.03)\n  g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur)\n  src.connect(bp).connect(g).connect(ctx.destination)\n  src.start()\n}\n\nexport function moveFigure(scene, flag, zone, [tx, ty]) {\n  const ts = scene.tileSize\n  flag.tileX = tx\n  flag.tileY = ty\n  const px = tx * ts + ts / 2, py = ty * ts + ts / 2\n  zone.x = px; zone.y = py\n  zone.setData('logicalX', px)\n  zone.setData('logicalY', py)\n}\n\nfunction figureTexture(scene, gid) {\n  const key = `skyeFigure_${gid}`\n  if (scene.textures.exists(key)) return key\n  const cv = scene.perspectiveGround?._getTileCanvas?.(gid)\n  if (!cv) return null\n  scene.textures.addCanvas(key, cv)\n  return key\n}\n\nexport function dash(scene, { flag, zone, to, onArrive }) {\n  const from = [flag.tileX, flag.tileY]\n  const b0 = figureBox(scene, ...from)\n  const key = figureTexture(scene, flag.visual?.gid)\n\n  const land = () => {\n    moveFigure(scene, flag, zone, to)\n    flag.hidden = false\n    onArrive?.()\n  }\n  // Nothing to animate with (off screen, texture not ready): just move.\n  if (!b0 || !key) { land(); return }\n\n  const b1 = figureBox(scene, ...to)\n  // Screen-space direction of travel.\n  let ux = 0, uy = -1\n  if (b1) { const dx = b1.x - b0.x, dy = b1.y - b0.y, m = Math.hypot(dx, dy) || 1; ux = dx / m; uy = dy / m }\n\n  flag.hidden = true\n  const img = scene.add.image(b0.x, b0.y, key).setOrigin(0.5, 1)\n    .setDisplaySize(b0.w, b0.h).setScrollFactor(0).setDepth(18)\n  const sx0 = img.scaleX, sy0 = img.scaleY\n\n  // 1. wind-up: a squat and a lean away from the direction of travel\n  scene.tweens.add({\n    targets: img, scaleX: sx0 * 1.12, scaleY: sy0 * 0.86, angle: -ux * 10,\n    duration: 170, ease: 'Quad.easeOut',\n    onComplete: () => {\n      // 2. the lunge: stretch, streak, gone\n      whoosh(scene)\n      speedLines(scene, b0, ux, uy)\n      dustPuff(scene, b0, -ux * 0.6)\n      scene.tweens.add({\n        targets: img,\n        x: b0.x + ux * b0.w * 2.2, y: b0.y + uy * b0.w * 2.2,\n        scaleX: sx0 * 0.7, scaleY: sy0 * 1.35, angle: ux * 18, alpha: 0,\n        duration: 130, ease: 'Quad.easeIn',\n        onComplete: () => {\n          img.destroy()\n          scene.time.delayedCall(420, () => arrive())\n        },\n      })\n    },\n  })\n\n  const arrive = () => {\n    const b = figureBox(scene, ...to)\n    if (!b) { land(); return }\n    const im = scene.add.image(b.x - ux * b.w * 2.2, b.y - uy * b.w * 2.2, key)\n      .setOrigin(0.5, 1).setDisplaySize(b.w, b.h).setScrollFactor(0).setDepth(18).setAlpha(0)\n    const ax = im.scaleX, ay = im.scaleY\n    im.setScale(ax * 0.7, ay * 1.35).setAngle(ux * 18)\n    whoosh(scene, 0.16, 0.22, 900, 3000)\n    speedLines(scene, b, ux, uy, true)\n    scene.tweens.add({\n      targets: im, x: b.x, y: b.y, alpha: 1, duration: 120, ease: 'Quad.easeOut',\n      onComplete: () => {\n        // 3. the skid: squash past the mark, settle, dust drifting on\n        dustPuff(scene, b, ux * 0.8, 12)\n        scene.tweens.add({\n          targets: im, scaleX: ax * 1.18, scaleY: ay * 0.82, angle: -ux * 6,\n          x: b.x + ux * b.w * 0.25, duration: 110, ease: 'Quad.easeOut', yoyo: true,\n          onComplete: () => {\n            scene.tweens.add({\n              targets: im, scaleX: ax, scaleY: ay, angle: 0, x: b.x,\n              duration: 180, ease: 'Back.easeOut',\n              onComplete: () => { im.destroy(); land() },\n            })\n          },\n        })\n      },\n    })\n  }\n}\n\n// A dunk: spray thrown up and falling back, rings spreading on the water.\nconst SPRAY = [0xdfeef5, 0xb8d4e3, 0x8fb3c9]\nexport function splash(scene, box) {\n  if (!box) return\n  const r = Math.max(3, box.w * 0.12)\n  for (let i = 0; i < 14; i++) {\n    const c = scene.add.circle(box.x + (Math.random() - 0.5) * box.w * 0.5, box.y - box.h * 0.1,\n      r * (0.5 + Math.random() * 0.6), SPRAY[i % SPRAY.length], 0.9).setScrollFactor(0).setDepth(17)\n    const up = box.h * (0.5 + Math.random() * 0.7)\n    const side = (Math.random() - 0.5) * box.w * 1.4\n    scene.tweens.add({ targets: c, x: c.x + side, y: c.y - up, duration: 260, ease: 'Quad.easeOut',\n      onComplete: () => scene.tweens.add({ targets: c, y: c.y + up * 1.1, alpha: 0, duration: 320,\n        ease: 'Quad.easeIn', onComplete: () => c.destroy() }) })\n  }\n  for (let k = 0; k < 3; k++) {\n    const g = scene.add.ellipse(box.x, box.y, box.w * 0.6, box.w * 0.22)\n      .setStrokeStyle(Math.max(1, box.w * 0.04), 0xdfeef5, 0.8).setScrollFactor(0).setDepth(16)\n    scene.tweens.add({ targets: g, scaleX: 2.6, scaleY: 2.6, alpha: 0, delay: k * 160,\n      duration: 900, ease: 'Sine.easeOut', onComplete: () => g.destroy() })\n  }\n  whoosh(scene, 0.28, 0.4, 700, 200)\n}\n",
 "js/game/scenes/locations/skye/skyeMaps.js": "// skyeMaps.js\n// Location: js/game/scenes/locations/skye/skyeMaps.js\n//\n// One tiny subclass per Skye map. Per-map tuning (sky, light, music,\n// onEnter hooks) goes here as each map gets real content.\n\nimport SkyeScene from './skyeScene.js'\nimport { SkyeCladach } from './skyeCladach.js'\nimport { SkyeLoch } from './skyeLoch.js'\n\n// SkyeCladach (the shore) and SkyeLoch carry Uathach's movement lesson:\n// see skyeCladach.js and skyeLoch.js\n\nexport class SkyeMachaire extends SkyeScene {\n  constructor() { super({ key: 'skye_machaire' }) }\n  getMapKey() { return 'skye_machaire' }\n}\n\nexport class SkyeFaiche extends SkyeScene {\n  constructor() { super({ key: 'skye_faiche' }) }\n  getMapKey() { return 'skye_faiche' }\n}\n\nexport class SkyeDroichead extends SkyeScene {\n  constructor() { super({ key: 'skye_droichead' }) }\n  getMapKey() { return 'skye_droichead' }\n}\n\nexport class SkyeDun extends SkyeScene {\n  constructor() { super({ key: 'skye_dun' }) }\n  getMapKey() { return 'skye_dun' }\n}\n\nexport const SKYE_SCENES = [SkyeCladach, SkyeLoch, SkyeMachaire, SkyeFaiche, SkyeDroichead, SkyeDun]\n",
 "public/data/skye/skyeLoch.js": "// skyeLoch.js\n// Location: public/data/skye/skyeLoch.js\n//\n// The loch: Uathach's tap-to-move lesson (js/game/scenes/locations/skye/\n// skyeLoch.js runs it; her lines during it are captions). This file only\n// holds her placement and what she says if tapped.\n//\n// The dialogues array is generated from tools/dialogue/drafts/skyeLoch.dlg\n//   node tools/dialogue/compile.mjs tools/dialogue/drafts/skyeLoch.dlg\n\nexport const skyeLochContent = {\n  objects: [],\n  npcs:    [],\n  fixedEncounters: [\n    {\n      id: 'uathach',\n      // Round A: across the first pool, on the middle bank. The scene\n      // dashes her to her round-B spot and off again (uathachSpots in the\n      // map JSON).\n      x: 18, y: 15,\n      radius: 1,\n      visual:   { gid: 9201, flat: false },\n      portrait: '/assets/npcs/sorcha.png',\n      dialogues: [\n\n        // ── node 0 — at the loch ──────────────────────────────────\n        {\n          hold: true,\n          ga: 'Ní ar do chosa.\\nFéach ar an áit a bhfuil tú ag dul.',\n          en: 'Not at your feet.\\nLook where you\\'re going.',\n        },\n\n      ],\n    },\n  ],\n}\n",
 "tools/dialogue/drafts/skyeLoch.dlg": "# skyeLoch — Uathach at the loch\n#\n# The lesson (stepping stones, dunks, the ring) is run by the scene and\n# spoken in captions -- see js/game/scenes/locations/skye/skyeLoch.js.\n# This is only what she says if the player taps her badge.\n#\n# IRISH IS A FIRST DRAFT -- check before shipping.\n\n@file skye/skyeLoch\n\n\n# ══════════════════════════════════════════════════════════════════════\n= node 0 — at the loch\n@hold\nNot at your feet.\n% Ní ar do chosa.\nLook where you're going.\n% Féach ar an áit a bhfuil tú ag dul.\n"
}

PATCHES = {}

MARKERS = {}

if not pathlib.Path('js/main.js').exists():
    sys.exit('Run from the repo root.')
if 'this._expectUndo' not in pathlib.Path('js/game/scenes/locations/skye/stepDrill.js').read_text():
    sys.exit('Run skye_step9.py first.')

plan = {}
for path, hs in PATCHES.items():
    s = pathlib.Path(path).read_text()
    if MARKERS[path] in s:
        plan[path] = 'skip'; continue
    for old, new in hs:
        if s.count(old) != 1:
            sys.exit(f'ABORT: anchor not found in {path} -- nothing written')
    plan[path] = 'patch'

for path, text in FILES.items():
    p = pathlib.Path(path); p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text); print('wrote   ', path)

for path, hs in PATCHES.items():
    if plan[path] == 'skip':
        print('skip    ', path, '(already applied)'); continue
    p = pathlib.Path(path); s = p.read_text()
    for old, new in hs: s = s.replace(old, new)
    p.write_text(s); print('patched ', path)

print('\nDone. Now: node tools/map-editor/generators/skye_gen.mjs')
